Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int N=10, M=1e6+7, K=200, p=1e9+7;
#define doge bitset<40>
int n, e[N], s[M], wf[K], q[N][K], f[N][N], ans[N][M];
doge op, wq[N][M];
unordered_map<doge,int> rt[N];

int get_input() {
    int res=0; char ch=getchar();
    while(ch<'0' || ch>'9') ch=getchar();
    while(ch>='0' && ch<='9') {
        res=res*10+ch-'0';
        ch=getchar();
    }
    return res;
}

long long power_mod(long long base, int exp) {
    long long res=1;
    while(exp>0) {
        if(exp&1) res=(res*base)%p;
        base=(base*base)%p;
        exp>>=1;
    }
    return res;
}

void compute_node(int u) {
    q[u][0]=0; int count_os=0, count_of=0;
    for(int i=0; i<(1<<n); i++) if(s[i]==u) {
        q[u][++q[u][0]]=i; wf[i]=++count_os;
    }
    for(int i=1; i<=e[u-1]; i++) {
        if(!ans[u-1][i]) continue;
        for(int h=1; h<(1<<n); h++) {
            long long prob=1;
            for(int c=0; c<n; c++) {
                if((1<<c)&h) prob=(prob*f[u][c+1])%p;
                else prob=(prob*(1-f[u][c+1]+p)%p);
            }
            doge c=wq[u-1][i], hc=op;
            bool changed=0;
            for(int x=1; x<=q[u-1][0]; x++) {
                if(c[x]==1) {
                    for(int t=0; t<n; t++) {
                        if(((1<<t)&h)&&(!(q[u-1][x]&(1<<t)))) {
                            hc[wf[q[u-1][x]|(1<<t)]]=1; changed=1;
                        }
                    }
                }
            }
            if(!changed) continue;
            int pos;
            if(rt[u][hc]==0) {
                rt[u][hc]=++count_of; e[u]++; wq[u][e[u]]=hc;
            }
            pos=rt[u][hc];
            ans[u][pos]=(ans[u][pos]+prob*ans[u-1][i])%p;
        }
    }
}

int main() {
    n=get_input();
    for(int i=0; i<=(1<<n); i++) s[i]=__builtin_popcount(i);
    for(int i=1; i<=n; i++)
        for(int j=1; j<=n; j++) f[i][j]=get_input()*power_mod(100,p-2)%p;
    q[0][0]=1; e[0]=1; ans[0][1]=1; wq[0][1][1]=1;
    for(int i=1; i<=n; i++) compute_node(i);
    cout<<ans[n][1]<<endl;
    return 0;
}
</original_code>
